package com.example.classmanagement.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.util.Date; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService {private final SecretKey key; private final long exp; public JwtService(@Value("${jwt.secret}")String s,@Value("${jwt.expiration-ms}")long e){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));exp=e;} public String create(String u){Date n=new Date();return Jwts.builder().subject(u).issuedAt(n).expiration(new Date(n.getTime()+exp)).signWith(key).compact();} public String user(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();}}
